&lt;/li&gt;
&lt;li data-local-id=&quot;525985e1597b&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
